audit.command:
command -v gh >/dev/null 2>&1 || exit 1
gh auth status >/dev/null 2>&1 || exit 1
info=$(gh api 'repos/{owner}/{repo}' --jq '.full_name + " " + .default_branch' 2>/dev/null) || exit 1
R=${info% *}; B=${info#* }
[ -n "$R" ] && [ -n "$B" ] || exit 1
O=${GH_ORG:-${R%%/*}}
gh api "repos/$R/vulnerability-alerts" --silent >/dev/null 2>&1 || { echo "Dependabot alerts disabled: $R"; exit 0; }
d=$(gh api "orgs/$O" --jq '.dependabot_alerts_enabled_for_new_repositories' 2>/dev/null) || d=null
[ "$d" = false ] && echo "Dependabot alerts not enabled by default for new repositories" || echo compliant

command -v gh >/dev/null 2>&1 || exit 1
gh auth status >/dev/null 2>&1 || exit 1
info=$(gh api 'repos/{owner}/{repo}' --jq '.full_name + " " + .default_branch' 2>/dev/null) || exit 1
R=${info% *}; B=${info#* }
[ -n "$R" ] && [ -n "$B" ] || exit 1
O=${GH_ORG:-${R%%/*}}
chk() {
  a=$(gh api "$1/actions/permissions" --jq '.allowed_actions // ""' 2>/dev/null) || return 1
  [ "$a" = selected ] || return 1
  g=$(gh api "$1/actions/permissions/selected-actions" --jq '.github_owned_allowed' 2>/dev/null) || return 1
  [ "$g" = true ]
}
chk "orgs/$O" && { echo compliant; exit 0; }
chk "repos/$R" && echo compliant
